export type TranslatedLanguage = keyof typeof translations

// Strings above use {{BRAND}} instead of a hardcoded brand name because this
// file is shared by two separately-deployed brands (see lib/brand.ts) —
// substituted here, once, rather than duplicating every string per brand.
function applyBrand(dict: Record<TranslationKey, string>): Record<TranslationKey, string> {
  const out = {} as Record<TranslationKey, string>
  for (const key of Object.keys(dict) as TranslationKey[]) {
    const value = dict[key]
    out[key] = value.includes('{{BRAND}}') ? value.split('{{BRAND}}').join(BRAND.name) : value
  }
  return out
}

export function getTranslations(lang: string): Record<TranslationKey, string> {
  const dict = (translations as Record<string, Partial<Record<TranslationKey, string>>>)[lang]
  if (!dict) return applyBrand(translations.en)
  // A language dict can lag behind newly-added keys. Merge over English
  // defaults so a missing translation falls back to English text, never to
  // a raw untranslated key string on screen.
  return applyBrand({ ...translations.en, ...dict })
}

export const TRANSLATED_LANGUAGES = Object.keys(translations) as TranslatedLanguage[]
